class DataProcessor {
  async processRecords(records: Record[]): Promise<ProcessedRecord[]> {
    // Collect unique IDs
    const userIds = [...new Set(records.map(r => r.userId))];
    const categoryIds = [...new Set(records.map(r => r.categoryId))];
    const allTagIds = [...new Set(records.flatMap(r => r.tagIds))];

    // Batch fetch all related data in parallel
    const [users, categories, tags] = await Promise.all([
      db.users.findByIds(userIds),
      db.categories.findByIds(categoryIds),
      db.tags.findByIds(allTagIds),
    ]);

    // Create lookup maps
    const userMap = new Map(users.map(u => [u.id, u]));
    const categoryMap = new Map(categories.map(c => [c.id, c]));
    const tagMap = new Map(tags.map(t => [t.id, t]));

    // Transform with O(1) lookups
    return records.map(record => ({
      id: record.id,
      userName: userMap.get(record.userId)!.name,
      categoryName: categoryMap.get(record.categoryId)!.name,
      tagNames: record.tagIds.map(id => tagMap.get(id)!.name),
      score: this.calculateScore(record),
      createdAt: record.createdAt,
    }));
  }
}
```

