**Event Hierarchy with Automatic Cascading**

```typescript
type EventHandler<T = any> = (payload: T) => void;

interface EventConfig {
  cascadesTo?: string[];
  auditAction?: string;
  auditEntity?: string;
}

class EventEmitter {
  private handlers = new Map<string, Set<EventHandler>>();
  private eventConfigs = new Map<string, EventConfig>();

  // Configure event relationships
  configureEvent(event: string, config: EventConfig): void {
    this.eventConfigs.set(event, config);
  }

  on<T>(event: string, handler: EventHandler<T>): () => void {
    if (!this.handlers.has(event)) {
      this.handlers.set(event, new Set());
    }
    this.handlers.get(event)!.add(handler);

    // Return unsubscribe function
    return () => this.handlers.get(event)?.delete(handler);
  }

  emit(event: string, payload: any): void {
    // Trigger primary event
    this.handlers.get(event)?.forEach(h => h(payload));

    // Handle cascading based on config
    const config = this.eventConfigs.get(event);
    if (config) {
      // Cascade to related events
      config.cascadesTo?.forEach(cascadeEvent => {
        this.handlers.get(cascadeEvent)?.forEach(h => h(payload));
      });

      // Audit logging
      if (config.auditAction && config.auditEntity) {
        this.handlers.get('auditLog')?.forEach(h => 
          h({ action: config.auditAction, entity: config.auditEntity, payload })
        );
      }
    }
  }
}

// Configuration
const emitter = new EventEmitter();

['userCreated', 'userUpdated', 'userDeleted'].forEach(event => {
  const action = event.replace('user', '').toLowerCase();
  emitter.configureEvent(event, {
    cascadesTo: ['dataChanged'],
    auditAction: action,
    auditEntity: 'user',
  });
});

['orderCreated', 'orderUpdated', 'orderDeleted'].forEach(event => {
  const action = event.replace('order', '').toLowerCase();
  emitter.configureEvent(event, {
    cascadesTo: ['dataChanged'],
    auditAction: action,
    auditEntity: 'order',
  });
});
```

## Risk Assessment
- Test coverage: Test cascading behavior with mock handlers
- Migration: Add config alongside, verify same events triggered
- Risk level: Medium - event system is foundational, test carefully

