**Saga Orchestrator Pattern**

```typescript
interface SagaStep<TContext> {
  name: string;
  execute: (context: TContext) => Promise<void>;
  compensate?: (context: TContext) => Promise<void>;
  critical?: boolean; // If true, failure aborts saga
}

class OrderSaga {
  private context: OrderSagaContext;

  private steps: SagaStep<OrderSagaContext>[] = [
    {
      name: 'validateInventory',
      critical: true,
      execute: async (ctx) => {
        for (const item of ctx.orderData.items) {
          const available = await this.inventoryService.checkAvailability(item.productId, item.quantity);
          if (!available) throw new Error(`Insufficient stock for ${item.productId}`);
        }
      },
    },
    {
      name: 'reserveInventory',
      critical: true,
      execute: async (ctx) => {
        for (const item of ctx.orderData.items) {
          await this.inventoryService.reserve(item.productId, item.quantity);
        }
      },
      compensate: async (ctx) => {
        for (const item of ctx.orderData.items) {
          await this.inventoryService.release(item.productId, item.quantity);
        }
      },
    },
    {
      name: 'processPayment',
      critical: true,
      execute: async (ctx) => {
        const payment = await this.paymentService.charge(ctx.orderData.paymentMethod, ctx.orderData.total);
        if (!payment.success) throw new Error('Payment failed');
        ctx.paymentId = payment.id;
      },
      compensate: async (ctx) => {
        if (ctx.paymentId) await this.paymentService.refund(ctx.paymentId);
      },
    },
    {
      name: 'createOrder',
      critical: true,
      execute: async (ctx) => {
        ctx.order = await this.orderRepo.create({ ...ctx.orderData, paymentId: ctx.paymentId, status: 'confirmed' });
      },
    },
    {
      name: 'scheduleShipping',
      critical: false, // Can retry later
      execute: async (ctx) => {
        await this.shippingService.schedulePickup(ctx.order!.id);
      },
    },
    {
      name: 'sendConfirmation',
      critical: false,
      execute: async (ctx) => {
        await this.emailService.sendOrderConfirmation(ctx.order!);
      },
    },
    {
      name: 'trackAnalytics',
      critical: false,
      execute: async (ctx) => {
        await this.analyticsService.track('order_placed', { orderId: ctx.order!.id });
      },
    },
  ];

  async execute(orderData: OrderInput): Promise<Order> {
    const context: OrderSagaContext = { orderData };
    const completedSteps: SagaStep<OrderSagaContext>[] = [];

    for (const step of this.steps) {
      try {
        await step.execute(context);
        completedSteps.push(step);
      } catch (error) {
        if (step.critical) {
          await this.rollback(completedSteps, context);
          throw error;
        }
        console.error(`Non-critical step ${step.name} failed:`, error);
      }
    }

    return context.order!;
  }

  private async rollback(steps: SagaStep<OrderSagaContext>[], context: OrderSagaContext) {
    for (const step of steps.reverse()) {
      await step.compensate?.(context).catch(console.error);
    }
  }
}
```

## Risk Assessment
- Test coverage: Test each step independently, test rollback scenarios
- Migration: Run both implementations in parallel, compare outcomes
- Risk level: High - order processing is business critical

