type BinaryOperation = (a: number, b: number) => number;

const operations: Record<string, BinaryOperation> = {
  add: (a, b) => a + b,
  subtract: (a, b) => a - b,
  multiply: (a, b) => a * b,
  divide: (a, b) => {
    if (b === 0) throw new Error('Division by zero');
    return a / b;
  },
  power: (a, b) => Math.pow(a, b),
  modulo: (a, b) => a % b,
  max: (a, b) => Math.max(a, b),
  min: (a, b) => Math.min(a, b),
};

class MathOperations {
  calculate(operation: string, a: number, b: number): number {
    const op = operations[operation];
    if (!op) throw new Error(`Unknown operation: ${operation}`);
    return op(a, b);
  }

  // Easy to extend
  static registerOperation(name: string, fn: BinaryOperation): void {
    operations[name] = fn;
  }

  // Easy to introspect
  static getAvailableOperations(): string[] {
    return Object.keys(operations);
  }
}

// Extension example
MathOperations.registerOperation('average', (a, b) => (a + b) / 2);
```

