type NodeRenderer = (node: TreeNode, indent: string) => string;

const nodeRenderers: Record<string, NodeRenderer> = {
  folder: (node, indent) => `${indent}[Folder] ${node.name}\n`,
  file: (node, indent) => `${indent}[File] ${node.name} (${node.size} bytes)\n`,
  link: (node, indent) => `${indent}[Link] ${node.name} -> ${node.target}\n`,
  image: (node, indent) => `${indent}[Image] ${node.name} (${node.width}x${node.height})\n`,
  document: (node, indent) => `${indent}[Doc] ${node.name} (${node.pages} pages)\n`,
};

class TreeRenderer {
  render(node: TreeNode, depth: number = 0): string {
    const indent = '  '.repeat(depth);
    const renderer = nodeRenderers[node.type];

    if (!renderer) {
      return `${indent}[Unknown] ${node.name}\n`;
    }

    let output = renderer(node, indent);

    // Handle children for container types
    if (node.children) {
      for (const child of node.children) {
        output += this.render(child, depth + 1);
      }
    }

    return output;
  }

  // Extensible
  static registerRenderer(type: string, renderer: NodeRenderer): void {
    nodeRenderers[type] = renderer;
  }
}

// Add new type without modifying TreeRenderer
TreeRenderer.registerRenderer('video', (node, indent) => 
  `${indent}[Video] ${node.name} (${node.duration}s)\n`
);
```

## Risk Assessment
- Test coverage: Test each renderer independently
- Migration: Extract renderers one at a time
- Risk level: Low - display logic, easy to verify visually

